<script>
(function(){
  "use strict";
  var NS="http://www.w3.org/2000/svg";
  var svg=document.getElementById("scene");
  function el(name,attr,parent){
    var e=document.createElementNS(NS,name);
    if(attr) for(var k in attr) e.setAttribute(k,attr[k]);
    if(parent) parent.appendChild(e);
    return e;
  }
  function pathGen(d,parent,extra){
    var a={d:d};
    if(extra) for(var k in extra)a[k]=extra[k];
    return el("path",a,parent);
  }

  /* ============ BEZIER RACE PATH ============ */
  var P0={x:150,y:755}, P1={x:600,y:610}, P2={x:1150,y:505}, P3={x:1500,y:345};
  function bez(t){
    var u=1-t;
    var x=u*u*u*P0.x+3*u*u*t*P1.x+3*u*t*t*P2.x+t*t*t*P3.x;
    var y=u*u*u*P0.y+3*u*u*t*P1.y+3*u*t*t*P2.y+t*t*t*P3.y;
    return {x:x,y:y};
  }
  function bezDeriv(t){
    var u=1-t;
    var x=3*u*u*(P1.x-P0.x)+6*u*t*(P2.x-P1.x)+3*t*t*(P3.x-P2.x);
    var y=3*u*u*(P1.y-P0.y)+6*u*t*(P2.y-P1.y)+3*t*t*(P3.y-P2.y);
    return {x:x,y:y};
  }
  // pre-sample cumulative length
  var SAMPLE=140, samples=[], Ltot=0;
  (function(){
    var prev=bez(0), i;
    for(i=0;i<=SAMPLE;i++){
      var p=bez(i/SAMPLE);
      var seg=Math.hypot(p.x-prev.x,p.y-prev.y);
      Ltot+=seg; samples.push(Ltot); prev=p;
    }
  })();
  function pointAtDist(d){
    // d in px along path (0..Ltot)
    for(var i=1;i<=SAMPLE;i++){
      if(samples[i]>=d){
        var t0=(i-1)/SAMPLE, t1=i/SAMPLE;
        var f=(d-samples[i-1])/(samples[i]-samples[i-1]);
        var t=t0+(t1-t0)*f;
        var p=bez(t), v=bezDeriv(t);
        var ang=Math.atan2(v.y,v.x)*180/Math.PI;
        var scale=1-(1-0.44)*(t);
        return {x:p.x,y:p.y,t:t,ang:ang,scale:scale,lx:v.y/Math.hypot(v.x,v.y),ly:-v.x/Math.hypot(v.x,v.y)};
      }
    }
    var p=bez(1),v=bezDeriv(1);
    return {x:p.x,y:p.y,t:1,ang:Math.atan2(v.y,v.x)*180/Math.PI,scale:0.44,lx:v.y/Math.hypot(v.x,v.y),ly:-v.x/Math.hypot(v.x,v.y)};
  }

  /* ============ BUILD ROAD ============ */
  (function buildRoad(){
    var road=document.getElementById("roadLayer");
    var n=70, left=[], right=[], center=[], i;
    var half0=185, half1=78;
    for(i=0;i<=n;i++){
      var t=i/n, p=bez(t), v=bezDeriv(t), L=Math.hypot(v.x,v.y);
      var nx=-v.y/L, ny=v.x/L, w=half0+(half1-half0)*t;
      left.push([(p.x+nx*w).toFixed(1),(p.y+ny*w).toFixed(1)]);
      right.push([(p.x-nx*w).toFixed(1),(p.y-ny*w).toFixed(1)]);
      center.push([p.x.toFixed(1),p.y.toFixed(1)]);
    }
    var d="M"+left.map(function(q){return q[0]+" "+q[1]}).join(" L");
    for(i=n;i>=0;i--) d+=" L"+right[i][0]+" "+right[i][1];
