    pathGen(d,road,{fill:"url(#road)"});
    // center dashed line
    pathGen("M"+center.map(function(q){return q[0]+" "+q[1]}).join(" L"),road,
      {fill:"none",stroke:"#f4e6c8",strokeWidth:5,strokeLinecap:"round","stroke-dasharray":"58 34",opacity:0.92});
    // sand kerbs (edges)
    var lPath="M"+left.map(function(q){return q[0]+" "+q[1]}).join(" L");
    var rPath="M"+right.map(function(q){return q[0]+" "+q[1]}).join(" L");
    pathGen(lPath+" L"+center[0][0]+" "+center[0][1]+" Z",road,{fill:"#e2b877",opacity:0.85});
    pathGen(rPath+" L"+center[0][0]+" "+center[0][1]+" Z",road,{fill:"#e2b877",opacity:0.45});
    // Start line (t=0.015) & Finish gantry (t=0.985)
    function line(tt,label,hi){
      var p=bez(tt), v=bezDeriv(tt), L=Math.hypot(v.x,v.y);
      var nx=-v.y/L, ny=v.x/L, w=half0+(half1-half0)*tt;
      var a1=[p.x+nx*w,p.y+ny*w], a0=[p.x-nx*w,p.y-ny*w];
      var band=el("line",{x1:a0[0],y1:a0[1],x2:a1[0],y2:a1[1],stroke:"#fff",strokeWidth:Math.max(10,w*2-8),strokeLinecap:"butt",opacity:0.92},road);
      var chk=el("line",{x1:a0[0],y1:a0[1],x2:a1[0],y2:a1[1],stroke:"#1c1c1c",strokeWidth:Math.max(10,w*2-8),"stroke-dasharray":"26 26",strokeLinecap:"butt",opacity:0.92},road);
      var tx=el("text",{x:p.x+nx*(w+16),y:p.y+ny*(w+6),"text-anchor":"middle",fill:"#ffe9c9","font-size":hi?34:26,"font-weight":900,"letter-spacing":2,transform:"rotate("+(-Math.atan2(v.y,v.x)*180/Math.PI+180)+" "+p.x+" "+p.y+")"},road);
      tx.textContent=label;
      void band; void chk;
    }
    line(0.012,"START",false);
    // finish gantry
    (function(){
      var tt=0.985, p=bez(tt), v=bezDeriv(tt), L=Math.hypot(v.x,v.y);
      var nx=-v.y/L, ny=v.x/L, w=half0+(half1-half0)*tt;
      var tan=Math.atan2(v.y,v.x)*180/Math.PI;
      var g=el("g",{transform:"translate("+p.x+" "+(p.y-8)+") rotate("+(tan+90)+")"},road);
      el("line",{x1:-w,y1:0,x2:w,y2:0,stroke:"#8a5a30",strokeWidth:10,strokeLinecap:"round"},g);
      var pole=el("g",{transform:"translate("+(w-6)+" 0)"},g);
      el("line",{x1:0,y1:0,x2:0,y2:-120,stroke:"#d8d8d8",strokeWidth:7},pole);
      // checkered flag on pole
