        }
      }
      fl.classList.add("flut");
      el("text",{x:0,y:-134,fill:"#ffe9c9","font-size":40,"font-weight":900,"letter-spacing":4},pole).textContent="FINISH";
      el("text",{x:0,y:-142,fill:"#ff9a5a","font-size":16,"text-anchor":"middle","letter-spacing":6},g).textContent="";
    })();
  })();

  /* ============ RACER VEHICLE GEOMETRY ============ */
