    el("path",{d:"M21 -10 l8 -2 M25 -8 l6 4 M23 -12 l4 -6",stroke:"#8a6a1c",strokeWidth:2.5,fill:"none",strokeLinecap:"round"},body);
    // head (white)
    var head=el("g",null,body);
    pathGen("M6 -142 C-2 -150 6 -160 16 -156 C26 -152 26 -140 18 -134 C12 -130 8 -136 6 -142 Z",head,{fill:"#f6f2e6"});
    // crest feathers
    pathGen("M4 -148 C-2 -158 -8 -154 -10 -162 C-4 -158 0 -154 4 -150 Z",head,{fill:"#f6f2e6"});
    pathGen("M8 -150 C2 -160 -2 -158 -6 -166 C0 -162 4 -158 8 -152 Z",head,{fill:"#efe9d8"});
