    pathGen("M18 -144 C24 -148 30 -144 26 -138 C24 -136 20 -138 18 -142 Z",head,{fill:"#f2b53a",stroke:"#c8912a",strokeWidth:2});
    // eye
    el("circle",{cx:13,cy:-148,r:2.6,fill:"#1c1c1c"},head);
    el("circle",{cx:13.7,cy:-148.7,r:1,fill:"#fff"},head);
    // brow
    pathGen("M10 -152 L16 -150",head,{fill:"none",stroke:"#cfc8b2",strokeWidth:2,strokeLinecap:"round"});

    // number plate
    el("rect",{x:4,y:-62,width:20,height:16,rx:3,fill:"#fff",stroke:"#999",strokeWidth:1},body);
