    var tag=el("g",null,g);
    el("path",{d:"M-2 0 L-7 -8 L3 -8 Z",fill:"#f7e6cc"},tag);
    el("rect",{x:-50,y:-24,width:110,height:22,rx:9,fill:"rgba(20,8,4,.66)",stroke:"#ffd76a",strokeWidth:1.4},tag);
    el("text",{x:5,y:-8,"text-anchor":"middle","font-size":12,"font-weight":700,"fill":"#ffe9b0","letter-spacing":0.5},tag).textContent="AQUILA";
    tag.setAttribute("transform","translate(4 -176)");

    racers.push({key:"eagle",root:root,bob:bob,crank:pa,rw:rw,fw:fw,wing:wing,wing2:wing2,head:head,tag:tag,
      name:"Aquila the Eagle",short:"AQUILA",vehicle:"Tricycle",
      r:42,base:140,amp:18,freq:0.5,phase:4.2,color:"#ffd76a",id:"#3",lap:0,cum:0,
      off:{x:0,y:-30},hop:0,hopV:0,wA:0});
  })();

  /* ============ HUD / LEADERBOARD ============ */
  var hud=document.getElementById("hudLayer");
  (function buildHud(){
    var g=el("g",{transform:"translate(1155 18)"},hud);
    el("rect",{x:0,y:0,width:430,height:168,rx:14,fill:"rgba(16,6,3,.72)",stroke:"rgba(255,190,120,.45)",strokeWidth:2},g);
    el("rect",{x:0,y:0,width:430,height:34,rx:14,fill:"rgba(120,40,20,.55)"},g);
    el("rect",{x:0,y:20,width:430,height:14,fill:"rgba(120,40,20,.55)"},g);
    el("text",{x:215,y:23,"text-anchor":"middle","font-size":17,"font-weight":900,"letter-spacing":3,fill:"#ffe9c2"},g).textContent="LIVE LEADERBOARD";
    window.__lb={g:g,rank:[],bar:[]};
    for(var i=0;i<3;i++){
      var y=44+i*42;
      var row=el("g",null,g);
      el("rect",{x:10,y:y-26,width:410,height:34,rx:8,fill:"rgba(255,255,255,.05)"},row);
      var rank=el("circle",{cx:32,cy:y-9,r:12,fill:"#222",stroke:"#666",strokeWidth:1.5},row);
      el("text",{x:32,y:y-4,"text-anchor":"middle","font-size":14,"font-weight":900,fill:"#fff"},rank);
      var nm=el("text",{x:52,y:y-6,"font-size":14,"font-weight":800,"fill":"#ffe9c2"},row);
      var vh=el("text",{x:52,y:y+8,"font-size":10.5,"fill":"#d9a578"},row);
      var bx=el("rect",{x:220,y:y-20,width:90,height:7,rx:3.5,fill:"rgba(255,255,255,.14)"},row);
      var bf=el("rect",{x:220,y:y-20,width:0,height:7,rx:3.5,fill:"#ffb36a"},row);
      el("text",{x:318,y:y-4,"font-size":11,"font-weight":700,fill:"#9fd8ff"},row);
      var pc=el("text",{x:318,y:y+7,"font-size":9.5,fill:"#c9d9e0"},row);
      window.__lb.rank.push({circle:rank,rankT:rank.firstChild||null,row:row,nm:nm,vh:vh,bf:bf,lbl:pc});
      window.__lb.rank[i].rankT=rank.childNodes[0];
    }
    // lap clock
    var lapg=el("g",null,g);
    el("text",{x:215,y:162,"text-anchor":"middle","font-size":12,"letter-spacing":1.5,fill:"#d9a578"},lapg);
    window.__lb.lapT=lapg.childNodes[0];

    // announcement
    var annY=250;
    var a=el("text",{x:800,y:annY,"text-anchor":"middle","font-size":44,"font-weight":900,"letter-spacing":2,fill:"#ffe9c2",opacity:0},hud);
    a.classList.add("annq");
    var a2=el("text",{x:800,y:annY+46,"text-anchor":"middle","font-size":22,"font-weight":700,fill:"#ffb36a",opacity:0},hud);
    a2.classList.add("annq");
    window.__ann={t2:a,txt:a,sub:a2};
    window.__ann.t3=a2;

    // countdown
    var cd=el("text",{x:800,y:300,"text-anchor":"middle","font-size":120,"font-weight":900,fill:"#ffd76a",opacity:0},hud);
    cd.classList.add("cd");
    var cds=el("text",{x:800,y:360,"text-anchor":"middle","font-size":22,"letter-spacing":6,fill:"#ffe9c2",opacity:0},hud);
    window.__cd={n:cd,sub:cds};
  })();

  /* ============ PARTICLES ============ */
  var fx=document.getElementById("fx");
  var particles=[], MAXP=320;
  function spawn(p){ if(particles.length<MAXP) particles.push(p); }
  function addParticle(x,y,r,type,vx,vy,life){
    spawn({x:x,y:y,r:r,t:type,vx:vx||0,vy:vy||0,l:life||600,age:0});
  }
  function renderParticles(){
    // clear old children (rebuild cheaply)
    while(fx.firstChild) fx.removeChild(fx.firstChild);
    var i;
    for(i=0;i<particles.length;i++){
      var p=particles[i];
      var f=1-p.age/p.l;
      if(p.t==="dust"){ el("ellipse",{cx:p.x,cy:p.y,rx:p.r*(0.5+0.5*f)*1.6,ry:p.r*f*1.1,fill:"#c9915f",opacity:f*0.5},fx); }
      else if(p.t==="smoke"){ el("circle",{cx:p.x,cy:p.y,r:p.r*(0.6+f*0.7),fill:"#cfd4d8",opacity:f*0.35},fx); }
      else if(p.t==="spark"){ el("circle",{cx:p.x,cy:p.y,r:p.r*f,fill:"#ffd76a",opacity:f,filter:"url(#glow)"},fx); }
    }
  }

  /* ============ MAIN LOOP ============ */
  var startT=performance.now(), last=startT;
  var state="count"; // count -> race
  var countPhase=0, cdLast=-1;
  var annQueue=[], annShow=false, annUntil=0;
  var lbOrder=[0,1,2], lbHighlight=0;

  function announce(sub, main, dur){
    annQueue.push({sub:sub,main:main,dur:dur||2600});
  }

  function speedFor(r, t){
    if(t<=1.8) return 8;
    var s=r.base + Math.sin(t*r.freq+r.phase)*r.amp + Math.sin(t*1.7+r.phase*2)*r.amp*0.35;
    if(r.key==="rabbit"){ s+=Math.sin(t*0.33)*26 + (Math.sin(t*2.9)>0.85 ? 40:0); }
    if(r.key==="eagle"){ s+=Math.sin(t*0.22+1)*18; }
    if(r.key==="turtle"){
      if(t<1.8){ s=0; }
      if(r.boost>0){ s=r.base+150; r.boost-=0; }
    }
    return s;
  }

  function frame(now){
    var dt=Math.min((now-last)/1000, 0.05);
    last=now;
    var t=(now-startT)/1000;

    // ---- countdown
    if(state==="count"){
      countPhase+=dt;
      var n=Math.ceil(1.8-countPhase);
      n=Math.max(n,0);
      if(n!==cdLast){
        cdLast=n;
        var cd=window.__cd;
        cd.n.setAttribute("opacity",1);
        cd.n.textContent = n>0 ? String(n) : "GO!";
        cd.n.classList.remove("cd"); void cd.n.offsetWidth; cd.n.classList.add("cd");
        cd.sub.setAttribute("opacity",1);
        cd.sub.textContent = n>0 ? "MARTIAN RING ROAD GRAND PRIX" : "";
      }
      if(countPhase>=1.8){ state="race"; announce("", "GO!",1200); }
    }

    // ---- update racers
    var i,r,pos,sp;
    for(i=0;i<racers.length;i++){
      r=racers[i];
      sp=speedFor(r,t);
      r.spd=sp;
      r.cum+=sp*dt;

      // finish-line crossing (lap boundary)
      var lap=Math.floor(r.cum/Ltot);
      if(lap>r.lap){
        if(lap-r.lap>0){
          r.lap=lap;
          annQueue.push({sub:r.vehicle+" crosses the line first!", main:r.short+" TAKES LAP "+lap+"!",dur:2400});
        } else r.lap=lap;
      }

      var d=((r.cum%Ltot)+Ltot)%Ltot;
      pos=pointAtDist(d);
      var sc=pos.scale;
      // bob
      var crank=0, want=lspd2=0;
      // wheel sync
      r.wA=(r.wA+sp/(r.r)*dt*57.2958)%(360*3);
      // bob with pedal cadence + per-character
      var bobY=0;
      if(r.key==="rabbit"){
        bobY=Math.abs(Math.sin(r.wA*0.11))*7 - 3.5 + Math.sin(t*6+r.phase)*1.5;
      } else if(r.key==="turtle"){
        bobY=Math.abs(Math.sin(r.wA*0.10))*4 - 2 + Math.sin(t*4+r.phase)*1.2;
      } else {
        bobY=Math.abs(Math.sin(r.wA*0.13))*5 - 2.5 + Math.sin(t*4.3+r.phase)*1.2;
      }
      // rabbit hops
      if(r.key==="rabbit" && t>1.8 && Math.sin(t*1.25+r.phase)>0.94){ r.hop=50; }
      if(r.hop>0){ r.hop-=dt*120; bobY-=r.hop*0.5*sc; }

      // translate/scale/rotate root
      var lean=Math.sin(t*(r.key==="eagle"?1.1:0.6)+r.phase)*1.4 + (r.key==="rabbit"? (r.hop*0.2):0);
      var ang=pos.ang+lean;
      r.root.setAttribute("transform",
        "translate("+pos.x.toFixed(1)+" "+pos.y.toFixed(1)+") rotate("+ang.toFixed(2)+") scale("+(sc).toFixed(3)+")");
      r.bob.setAttribute("transform","translate(0 "+bobY.toFixed(1)+")");

      // wheels spin
      var wdeg=(r.wA%(360)).toFixed(1);
      r.rw.spin.setAttribute("transform","rotate("+wdeg+")");
      r.fw.spin.setAttribute("transform","rotate("+wdeg+")");

      // crank (sync with wheels: crankR ~ spokes)
      if(r.crank){
        var ca=(-r.wA* (r.r/ (r.r*0.32)) )%360;
        r.crank.setAttribute("transform","rotate("+ca.toFixed(1)+")");
      }
      // decorations
      if(r.earL){ 
        var ea=Math.sin(t*9+r.phase)*8; 
        r.earL.setAttribute("transform","rotate("+ea.toFixed(1)+" 44 -146)");
      }
      if(r.earR){ r.earR.setAttribute("transform","rotate("+(-Math.sin(t*9+r.phase)*10+14).toFixed(1)+" 52 -147)"); }
      if(r.scarf){ r.scarf.setAttribute("transform","rotate("+(Math.sin(t*13+r.phase)*9).toFixed(1)+" 40 -120)"); }
      if(r.wing){ r.wing.setAttribute("transform","rotate("+(Math.sin(t*3.5+r.phase)*20).toFixed(1)+" 0 -118)"); }
      if(r.wing2){ r.wing2.setAttribute("transform","rotate("+(Math.sin(t*3.5+r.phase+Math.PI)*26).toFixed(1)+" 0 -108)"); }
      if(r.shell){ r.shell.setAttribute("transform","rotate("+(Math.sin(t*2.6+r.phase)*3).toFixed(1)+" 0 -104)"); }
      if(r.head && r.key==="turtle"){ r.head.setAttribute("transform","translate("+(Math.sin(t*2.2)*2).toFixed(1)+" 0)"); }
      if(r.tag){ r.tag.setAttribute("transform","translate("+(5).toFixed(0)+" "+(r.off&&r.off.y?r.off.y:-150)+")"); }

      // ---- particles: exhaust + dust
      var speedx=sp;
      if(t>1.8){
        // dust puffs behind rear wheel
        var wx=pos.x - Math.cos(pos.ang*Math.PI/180)*(r.r*1.4)*sc;
        var wy=pos.y - Math.sin(pos.ang*Math.PI/180)*(r.r*1.4)*sc - r.r*1.05*sc + bobY*sc;
        if(Math.random()<0.35) addParticle(wx+(Math.random()-0.5)*10*sc, wy+(Math.random()-0.5)*4*sc, (6+Math.random()*6)*sc,"dust",0,0,420);
        if(r.key==="rabbit" && Math.random()<0.5) addParticle(wx,wy,5*sc,"dust",0,0,300);
        // turtle exhaust smokes
        if(r.key==="turtle"){
          var ex=pos.x - Math.cos(pos.ang*Math.PI/180)*(70*sc);
          var ey=pos.y - Math.sin(pos.ang*Math.PI/180)*(70*sc) - 19*sc;
          if(Math.random()<0.5) addParticle(ex,ey,(7+Math.random()*7)*sc,"smoke",0,-6*sc,620);
          if(r.boost>0 && Math.random()<0.7) addParticle(ex,ey,(8+Math.random()*4)*sc,"spark",0,-10*sc,300);
        }
      }
      r.dist=d; r.scale=sc; r.bobY=bobY; r.ang=pos.ang; r.pos=pos;
    }

    // ---- turtle boost timer
    var tr=racers[1];
    if(state==="race" && t>2){
      var cycle=Math.sin(t*0.14);
      if(cycle>0.72) tr.boost=1; else if(cycle<-0.5) tr.boost=0;
    }

    // ---- leaderboard + crossing order (by cumulative distance)
    var order=racers.slice().sort(function(a,b){ return b.cum-a.cum; });
    for(i=0;i<order.length;i++){
      var rr=order[i]; rr.rank=i+1;
    }
    // reverse mapping into lb rows (row 0 = rank 1)
    for(i=0;i<3;i++){
      var rc=window.__lb.rank[i], r2=order[i];
      rc.nm.textContent=r2.short+"  ·  "+r2.vehicle;
      rc.vh.textContent=r2.name;
      var pct=((r2.cum%Ltot)/Ltot)*100;
      rc.bf.setAttribute("width",(90*pct/100).toFixed(1));
      rc.lbl.textContent=(pct).toFixed(0)+"%";
      // medal colors
      rc.row.firstChild.setAttribute("fill", i===0?"rgba(255,215,0,.28)": i===1?"rgba(200,200,210,.22)": i===2?"rgba(205,127,50,.22)":"rgba(255,255,255,.05)");
    }

    // ---- announcement queue
    if(!annShow && annQueue.length){
      var a=annQueue.shift();
      window.__ann.txt.textContent=a.main;
      window.__ann.sub.textContent=a.sub;
      var d1=document.createElement("div"); void(d1);
      window.__ann.txt.setAttribute("opacity",1);
      window.__ann.sub.setAttribute("opacity",1);
      window.__ann.txt.style.transform="none";
      window.__ann.txt.classList.remove("annq"); void(window.__ann.txt.getBoundingClientRect());
      window.__ann.txt.classList.add("annp");
      window.__ann.sub.classList.remove("annq");
      window.__ann.sub.classList.add("annp");
      annShow=true; annUntil=now+(a.dur||2600);
    } else if(annShow && now>annUntil){
      window.__ann.txt.setAttribute("opacity",0);
      window.__ann.sub.setAttribute("opacity",0);
      window.__ann.txt.classList.remove("annp");
      window.__ann.sub.classList.remove("annp");
      annShow=false;
    }

    // ---- lap counts in leaderboard
    window.__lb.lapT.textContent = "LAP  "+(order[0].lap+1);
    if(state==="race" && t>2.2){
      var lbi=order.indexOf? order2=0:0;
    }

    renderParticles();
    particles.forEach(function(p){ p.age+=dt*1000; p.x+=p.vx*dt; p.y+=p.vy*dt; if(p.age>p.l) p.dead=true; });
    particles=particles.filter(function(p){ return !p.dead; });

    requestAnimationFrame(frame);
  }
  requestAnimationFrame(frame);
})();
</script>
